"""Loudness and ReplayGain tests."""

import subprocess
from pathlib import Path

import pytest

from integrations.audio import AudioError, Loudness, ReplayGain, measure_loudness, replaygain


def _tone(path: Path, amplitude: float, seconds: float = 3) -> Path:
    """1 kHz tone generated by ffmpeg."""
    subprocess.run(  # noqa: S603
        ["ffmpeg", "-nostdin", "-v", "error", "-y", "-f", "lavfi",  # noqa: S607
         "-i", f"aevalsrc={amplitude}*sin(2*PI*1000*t):s=48000:d={seconds}", str(path)],
        check=True,
    )  # fmt: skip
    return path


def _measure_alone(path: Path) -> float:
    """ffmpeg's ``I``, read by hand as a reference."""
    out = subprocess.run(  # noqa: S603
        ["ffmpeg", "-nostdin", "-nostats", "-i", str(path),  # noqa: S607
         "-af", "ebur128", "-f", "null", "-"],
        capture_output=True, text=True, check=True,
    ).stderr  # fmt: skip
    summary = out[out.rindex("Summary:") :]
    return float(summary.split("I:")[1].split()[0])


def test_tone_at_minus_6_db(tmp_path: Path) -> None:
    loudness = measure_loudness([_tone(tmp_path / "t.flac", 0.5)])
    # BS.1770: a 1 kHz sine at 0 dBFS reads −3.01 LUFS, so at −6 dBFS it reads −9.01.
    assert loudness.lufs == pytest.approx(-9.0, abs=0.1)
    assert loudness.peak == pytest.approx(0.5, abs=0.01)


def test_album_is_measured_over_the_union_of_its_tracks(tmp_path: Path) -> None:
    loud = _tone(tmp_path / "loud.flac", 0.5)
    quiet = _tone(tmp_path / "quiet.mp3", 0.05)
    joined = tmp_path / "joined.flac"
    subprocess.run(  # noqa: S603
        ["ffmpeg", "-nostdin", "-v", "error", "-y", "-i", str(loud), "-i", str(quiet),  # noqa: S607
         "-filter_complex", "[0:a][1:a]concat=n=2:v=0:a=1", str(joined)],
        check=True,
    )  # fmt: skip
    album = measure_loudness([loud, quiet])
    assert album.lufs == pytest.approx(_measure_alone(joined), abs=0.1)
    # The album peak is the largest.
    assert album.peak == pytest.approx(0.5, abs=0.01)


def test_unreadable_file_raises(tmp_path: Path) -> None:
    bad = tmp_path / "bad.mp3"
    bad.write_bytes(b"not audio")
    with pytest.raises(AudioError):
        measure_loudness([bad])


@pytest.mark.parametrize("error", [OSError("no ffmpeg"), subprocess.TimeoutExpired("ffmpeg", 1)])
def test_missing_binary_or_timeout(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, error: Exception
) -> None:
    def boom(*args: object, **kwargs: object) -> None:
        raise error

    path = _tone(tmp_path / "t.flac", 0.5)
    monkeypatch.setattr(subprocess, "run", boom)
    with pytest.raises(AudioError):
        measure_loudness([path])


def test_no_files_raises() -> None:
    with pytest.raises(AudioError):
        measure_loudness([])


def test_replaygain_uses_the_minus_18_lufs_reference() -> None:
    gain = replaygain(Loudness(lufs=-9.0, peak=0.5), Loudness(lufs=-20.0, peak=0.9))
    assert gain == ReplayGain(track_gain_db=-9.0, track_peak=0.5, album_gain_db=2.0, album_peak=0.9)


def test_replaygain_without_album() -> None:
    gain = replaygain(Loudness(lufs=-14.0, peak=1.0), None)
    assert (gain.album_gain_db, gain.album_peak) == (None, None)
